import java.util.*;
import java.io.*;

public class Main {
    static IO io = new IO();
    public static void main(String[] args) {

        int n[] = new int[10];
        for (int i=0; i<10; i++) n[i] = io.nextInt();
        Arrays.sort(n);
        System.out.println(n[9]);
        System.out.println(n[8]);
        System.out.println(n[7]);

    }

    static class IO extends PrintWriter {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        IO() {
            this(System.in);
        }

        IO(InputStream source) {
            super(System.out);
            this.in = source;
        }

        boolean hasNextByte() {
            if (ptr < buflen) return true;
            else {
                ptr = 0;
                try {
                    buflen = in.read(buffer);
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (buflen <= 0) return false;
            }
            return true;
        }

        int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            else return -1;
        }

        boolean isPrintableChar(int c) {
            return 33 <= c && c <= 126;
        }

        void skipUnprintable() {
            while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;
        }

        boolean hasNext() {
            skipUnprintable();
            return hasNextByte();
        }

        long nextLong() {
            if (!hasNext()) throw new NoSuchElementException();
            long n = 0;
            boolean minus = false;
            int b = readByte();
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            if (b < '0' || '9' < b) throw new NumberFormatException();
            while (true) {
                if ('0' <= b && b <= '9') {
                    n *= 10;
                    n += b - '0';
                } else if (b == -1 || !isPrintableChar(b)) return minus ? -n : n;
                else throw new NumberFormatException();
                b = readByte();
            }
        }

        int nextInt() {
            long nl = nextLong();
            if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
            return (int) nl;
        }

        public void close() {
            super.close();
            try {
                in.close();
            } catch (IOException ignored) {
            }
        }
    }
}

import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int[] array = new int[10];
		for(int i = 0; i < array.length; i++)
		array[i] = sc.nextInt();
		array = mergeSort(array);
		for(int i = 0; i < 3; i++)
		System.out.println(array[i]);
		}

		public static int[] mergeSort(int[] array) {
		if(array.length <= 1)
		return array;
		int[] head = split(array, 0, array.length / 2);
		int[] tail = split(array, array.length / 2, array.length);
		return merge(mergeSort(head), mergeSort(tail));
		}

		private static int[] split(int[] array, int start, int end) {
		int[] newArray = new int[end-start];
		for(int i = start, j = 0; i < end; i++, j++)
		newArray[j] = array[i];
		return newArray;
		}

		private static int[] merge(int[] a, int[] b) {
		int[] merged = new int[a.length + b.length];
		for(int i = 0, j = 0, k = 0; i < a.length + b.length; i++) {
		if(j == a.length || k == b.length)
		merged[i] = (j == a.length ? b[k++] : a[j++]);
		else
		merged[i] = (a[j] > b[k] ? a[j++] : b[k++]);
		}
		return merged;
		}
		}

